package com.fasterxml.jackson.databind.util;

import com.fasterxml.jackson.core.*;
import com.fasterxml.jackson.core.JsonFactory;
import com.fasterxml.jackson.core.JsonGenerator;
import com.fasterxml.jackson.core.JsonParser;
import com.fasterxml.jackson.core.JsonToken;
import com.fasterxml.jackson.core.base.ParserMinimalBase;
import com.fasterxml.jackson.core.json.JsonReadContext;
import com.fasterxml.jackson.core.json.JsonWriteContext;
import com.fasterxml.jackson.core.util.ByteArrayBuilder;
import com.fasterxml.jackson.databind.*;
import com.fasterxml.jackson.databind.ObjectMapper;
import com.fasterxml.jackson.databind.util.TokenBuffer;
import java.io.*;
import java.io.IOException;
import java.io.StringWriter;
import java.math.*;
import java.math.BigDecimal;
import java.math.BigInteger;
import java.util.*;
import java.util.TreeMap;
import org.junit.*;
import org.junit.Before;
import org.junit.Test;
import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;

public class TokenBuffer_copyCurrentStructure_TriageGen2Test {

    private ObjectMapper mapper;
    private JsonFactory factory;

    @Before
    public void setUp() {
        mapper = new ObjectMapper();
        factory = new JsonFactory();
    }

    /**
     * Tests simple value copying (default branch/case).
     */
    @Test
    public void testCopyCurrentStructure_SimpleValue() throws IOException {
        String json = "\"test-value\"";
        TokenBuffer tb = new TokenBuffer(mapper);

        try (JsonParser jp = factory.createParser(json)) {
            jp.nextToken(); // Move to VALUE_STRING
            tb.copyCurrentStructure(jp);
        }

        StringWriter sw = new StringWriter();
        tb.serialize(sw);
        assertEquals("\"test-value\"", sw.toString());
    }

    /**
     * Tests START_ARRAY branch and recursive calls.
     */
    @Test
    public void testCopyCurrentStructure_Array() throws IOException {
        String json = "[1, \"two\", {\"three\": 3}]";
        TokenBuffer tb = new TokenBuffer(mapper);

        try (JsonParser jp = factory.createParser(json)) {
            jp.nextToken(); // Move to START_ARRAY
            tb.copyCurrentStructure(jp);
        }

        StringWriter sw = new StringWriter();
        tb.serialize(sw);
        // Note: Jackson might format slightly differently, but content should match
        assertEquals("[1,\"two\",{\"three\":3}]", sw.toString().replace(" ", ""));
    }

    /**
     * Tests START_OBJECT branch and recursive calls.
     */
    @Test
    public void testCopyCurrentStructure_Object() throws IOException {
        String json = "{\"key\":\"value\"}";
        TokenBuffer tb = new TokenBuffer(mapper);

        try (JsonParser jp = factory.createParser(json)) {
            jp.nextToken(); // Move to START_OBJECT
            tb.copyCurrentStructure(jp);
        }

        StringWriter sw = new StringWriter();
        tb.serialize(sw);
        assertEquals("{\"key\":\"value\"}", sw.toString().replace(" ", ""));
    }

    /**
     * Tests the FIELD_NAME logic (if t == FIELD_NAME).
     * This triggers the first if block and the fall-through.
     */
    @Test
    public void testCopyCurrentStructure_WithFieldName() throws IOException {
        String json = "{\"field\":\"value\"}";
        TokenBuffer tb = new TokenBuffer(mapper);

        try (JsonParser jp = factory.createParser(json)) {
            jp.nextToken(); // START_OBJECT
            jp.nextToken(); // FIELD_NAME
            tb.copyCurrentStructure(jp);
        }

        StringWriter sw = new StringWriter();
        tb.serialize(sw);
        assertEquals("{\"field\":\"value\"}", sw.toString().replace(" ", ""));
    }

    /**
     * Tests the _mayHaveNativeIds = true branch.
     * This covers the _checkNativeIds calls in both the FIELD_NAME block and the general block.
     */
    @Test
    public void testCopyCurrentStructure_WithNativeIds() throws IOException {
        // Use the constructor that enables native IDs
        TokenBuffer tb = new TokenBuffer(mapper, true);
        String json = "{\"id\": 1}";

        try (JsonParser jp = factory.createParser(json)) {
            jp.nextToken(); // START_OBJECT
            jp.nextToken(); // FIELD_NAME
            tb.copyCurrentStructure(jp);
        }

        StringWriter sw = new StringWriter();
        tb.serialize(sw);
        // Even with native IDs enabled, if no actual ID is provided in parser, 
        // it should behave like a standard object copy.
        assertEquals("{\"id\":1}", sw.toString().replace(" ", ""));
    }

    /**
     * Tests complex nested structure to ensure maximum recursion coverage.
     */
    @Test
    public void testCopyCurrentStructure_DeeplyNested() throws IOException {
        String json = "{\"a\":[{\"b\":{\"c\":1}}]}";
        TokenBuffer tb = new TokenBuffer(mapper);

        try (JsonParser jp = factory.createParser(json)) {
            jp.nextToken(); // START_OBJECT
            tb.copyCurrentStructure(jp);
        }

        StringWriter sw = new StringWriter();
        tb.serialize(sw);
        assertEquals("{\"a\":[{\"b\":{\"c\":1}}]}", sw.toString().replace(" ", ""));
    }

    /**
     * Tests the default case for other tokens (null, boolean, number).
     */
    @Test
    public void testCopyCurrentStructure_VariousPrimitives() throws IOException {
        String[] primitives = ["true", "false", "null", "123", "45.67"];
        for (String p : primitives) {
            TokenBuffer tb = new TokenBuffer(mapper);
            try (JsonParser jp = factory.createParser("\"" + p + "\"")) {
                // We wrap in quotes to ensure it's treated as a string for the parser 
                // or we just use the raw primitive. Let's use raw.
                try (JsonParser jpRaw = factory.createParser(p)) {
                    jpRaw.nextToken();
                    tb.copyCurrentStructure(jpRaw);
                }
            }
            StringWriter sw = new StringWriter();
            tb.serialize(sw);
            assertEquals(p, sw.toString());
        }
    }
}
